"""Text-to-SQL harness: draft -> execute -> deterministic fan-out fix / optional repair call.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness (e.g. "system_prompt.md")
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    raw = (text or "").strip()
    # Fall back to the last statement-looking line if prose surrounds bare SQL.
    lines = [ln.strip() for ln in raw.splitlines() if ln.strip()]
    for i, ln in enumerate(lines):
        if re.match(r"(?i)^(select|with)\b", ln):
            return "\n".join(lines[i:]).rstrip(";").strip()
    return raw.rstrip(";").strip()


def _fmt_rows(res):
    try:
        cols = ", ".join(str(c) for c in res.get("columns") or [])
        rows = res.get("rows") or []
        head = "; ".join(str(r) for r in rows[:5])
        return f"columns: [{cols}]\nfirst rows: {head}"
    except Exception:
        return ""


# ---------------------------------------------------------------------------
# Join fan-out detection / deterministic de-duplication.
# A one-to-many join can repeat an otherwise correct answer row; the query runs
# fine and returns rows, so error/empty-result checks never notice it.
# ---------------------------------------------------------------------------

_AGG_RE = re.compile(
    r"(?i)\b(count|sum|avg|total|min|max|group_concat)\s*\("
)
_SKIP_RE = re.compile(
    r"(?i)\b(distinct|group\s+by|having|limit|union|intersect|except|"
    r"over\s*\(|insert|update|delete|create|drop|alter|attach|pragma)\b"
)
_JOIN_RE = re.compile(r"(?i)\bjoin\b")


def _mask_literals(sql):
    """Blank out string literals and quoted identifiers, keeping offsets."""
    out = []
    quote = None
    for ch in sql:
        if quote:
            out.append(" ")
            if ch == quote:
                quote = None
        elif ch in ("'", '"', "`"):
            quote = ch
            out.append(" ")
        else:
            out.append(ch)
    return "".join(out)


def _top_level_positions(masked):
    """Yield (index, char) for characters at paren depth 0."""
    depth = 0
    for i, ch in enumerate(masked):
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        elif depth == 0:
            yield i, ch


def _outer_select_span(sql, masked):
    """Return (start, end) of the outer select list, or None if not a plain SELECT."""
    m = re.match(r"\s*select\b", masked, re.I)
    if not m:
        return None
    start = m.end()
    depth = 0
    for i in range(start, len(masked)):
        ch = masked[i]
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        elif depth == 0 and masked[i:i + 4].lower() == "from" and (
            i == 0 or not (masked[i - 1].isalnum() or masked[i - 1] == "_")
        ) and (
            i + 4 >= len(masked)
            or not (masked[i + 4].isalnum() or masked[i + 4] == "_")
        ):
            return start, i
    return None


def _fanout_candidate(sql):
    """True only for a plain joined SELECT where DISTINCT would be a safe fix."""
    if not sql:
        return False
    masked = _mask_literals(sql)
    if ";" in masked:
        return False
    if _SKIP_RE.search(masked) or _AGG_RE.search(masked):
        return False
    if not _JOIN_RE.search(masked):
        return False
    span = _outer_select_span(sql, masked)
    if span is None:
        return False
    start, end = span
    select_list = masked[start:end]
    # Only rewrite when every projected item lives at the top level (no scalar
    # subqueries whose internals we would be guessing about).
    if "(" in select_list:
        return False
    return True


def _add_distinct(sql):
    masked = _mask_literals(sql)
    span = _outer_select_span(sql, masked)
    if span is None:
        return None
    start, _end = span
    return sql[:start] + " DISTINCT" + sql[start:]


def _count_of(env, wrapped_expr):
    """Row count of a wrapped query, or None when it cannot be measured."""
    try:
        res = env.execute("SELECT COUNT(*) FROM (%s)" % wrapped_expr, max_rows=1)
    except Exception:
        return None
    if not isinstance(res, dict) or not res.get("ok"):
        return None
    rows = res.get("rows") or []
    if not rows:
        return None
    first = rows[0]
    try:
        val = first[0] if isinstance(first, (list, tuple)) else first
        return int(val)
    except Exception:
        return None


def _dedup_fanout(sql, env):
    """If the draft repeats identical rows because of join fan-out, add DISTINCT.

    Returns the rewritten query only when it executes and yields exactly the
    de-duplicated row count; otherwise returns the original draft unchanged.
    """
    if not _fanout_candidate(sql):
        return sql
    total = _count_of(env, sql)
    if total is None or total < 2:
        return sql
    uniq = _count_of(env, "SELECT DISTINCT * FROM (%s)" % sql)
    if uniq is None or uniq < 1 or uniq >= total:
        return sql
    fixed = _add_distinct(sql)
    if not fixed:
        return sql
    try:
        res = env.execute(fixed, max_rows=20)
    except Exception:
        return sql
    if not isinstance(res, dict) or not res.get("ok"):
        return sql
    if _count_of(env, fixed) != uniq:
        return sql
    return fixed


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)

    user = (
        f"Database: {task['db_id']}\n\nSchema:\n{env.schema(task['db_id'])}\n\nQuestion: {task['question']}"
    )
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += f"\n\nColumn descriptions:\n{desc.strip()[:4000]}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    # Execution check: only spend the second call when something looks wrong.
    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = None

    if not isinstance(res, dict):
        return {"sql": sql}

    ok = res.get("ok")
    n_rows = res.get("n_rows")
    if ok and n_rows:
        # Runs and returns rows: the remaining silent risk is join fan-out.
        return {"sql": _dedup_fanout(sql, env)}

    if ok and not n_rows:
        feedback = (
            "Your query executed successfully but returned ZERO rows. For this question an empty "
            "result is almost certainly wrong. Likely causes: a string literal that does not match "
            "the stored values (case, trailing/leading spaces, abbreviations, partial text), an "
            "over-restrictive WHERE, or a wrong join key/column.\n"
            "Re-check the literal values against the schema and question wording: prefer LIKE with "
            "%...% around the distinctive part of the text (trim stray spaces), and compare "
            "case-insensitively when unsure. Also reconsider whether the question expects all "
            "columns of an entity rather than one attribute.\n"
            "Return ONE corrected SQLite query in a single ```sql code block."
        )
    else:
        feedback = (
            f"Your query failed with error: {res.get('error')}\n"
            "Fix the table/column names and syntax using the schema exactly as given. "
            "Return ONE corrected SQLite query in a single ```sql code block."
        )

    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": feedback})
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}

    # Accept the repair unless it is clearly worse than a working draft.
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = None
    if isinstance(res2, dict) and not res2.get("ok") and ok:
        return {"sql": sql}
    if isinstance(res2, dict) and res2.get("ok") and res2.get("n_rows"):
        return {"sql": _dedup_fanout(sql2, env)}
    return {"sql": sql2}

proposal.raw:
**Diagnosis.** Three of the four current failures (sp0536, sp0600, sp0755) are *silent* semantic errors on queries that execute fine and return rows, so the incumbent's error/zero-row trigger never fires. Two of them (sp0536: 8 vs 5 rows with an exactly repeated name triple; sp0600: `['music'], ['music']`) are join fan-out multiplicity errors — the query is otherwise correct, only the row multiset is inflated by a one-to-many join.

r1 tried this direction twice and failed for mechanical reasons, not because the signal is wrong: s1's probe used illegal SQLite (`COUNT(DISTINCT sub.*)`), s2 spent a whole policy call on the repair and lost 6.7 pts (the model rewrote more than the multiplicity). So this candidate keeps the detector but makes it **deterministic**: legal SQL (`SELECT COUNT(*) FROM (SELECT DISTINCT * FROM (<draft>))` vs `COUNT(*)` over the same wrapped draft), gated to plain SELECTs with a JOIN and no DISTINCT/GROUP BY/aggregate/LIMIT, and repairs by injecting `DISTINCT` into the outer select list — no second policy call, no re-interpretation risk, negligible token cost. The rewrite is accepted only if it executes and its row count equals the deduped count; otherwise the original draft is returned untouched. sp0755 (under-projection) and sp0894 (wrong relationship semantics) are deliberately out of scope for this single edit.

